begin;
create table if not exists public.referral_profiles(user_id uuid primary key references auth.users(id) on delete cascade,code text not null unique,created_at timestamptz not null default now());
create table if not exists public.referral_attributions(id uuid primary key default gen_random_uuid(),referred_id uuid not null unique references auth.users(id) on delete cascade,referrer_id uuid not null references auth.users(id) on delete cascade,referral_code text not null,attributed_at timestamptz not null default now(),expires_at timestamptz not null,constraint referral_no_self check(referred_id<>referrer_id));
create table if not exists public.referral_rate_config(plan_id text primary key,commission_rate numeric(6,5) not null check(commission_rate>=0 and commission_rate<=0.50),enabled boolean not null default true,updated_at timestamptz not null default now());
insert into public.referral_rate_config(plan_id,commission_rate,enabled) values('free',0.15,true),('starter',0.20,true),('pro',0.22,true),('elite',0.24,true),('ultra',0.25,true),('prime',0.25,true),('enterprise',0.25,true) on conflict(plan_id) do nothing;
create table if not exists public.referral_rewards(id uuid primary key default gen_random_uuid(),attribution_id uuid not null unique references public.referral_attributions(id) on delete restrict,subscription_id uuid not null unique references public.subscriptions(id) on delete restrict,referrer_id uuid not null references auth.users(id) on delete restrict,referred_id uuid not null references auth.users(id) on delete restrict,referrer_plan_id text not null,referred_plan_id text not null,qualifying_amount numeric(14,2) not null check(qualifying_amount>=0),commission_rate numeric(6,5) not null,commission_amount numeric(14,2) not null check(commission_amount>=0),status text not null default 'pending' check(status in('pending','approved','paid','rejected')),approved_at timestamptz,paid_at timestamptz,created_at timestamptz not null default now());
create index if not exists referral_rewards_referrer_idx on public.referral_rewards(referrer_id,created_at desc);create index if not exists referral_attributions_referrer_idx on public.referral_attributions(referrer_id,attributed_at desc);
alter table public.referral_profiles enable row level security;alter table public.referral_attributions enable row level security;alter table public.referral_rate_config enable row level security;alter table public.referral_rewards enable row level security;
drop policy if exists referral_profiles_own_read on public.referral_profiles;create policy referral_profiles_own_read on public.referral_profiles for select using(user_id=auth.uid());
drop policy if exists referral_attributions_party_read on public.referral_attributions;create policy referral_attributions_party_read on public.referral_attributions for select using(referred_id=auth.uid() or referrer_id=auth.uid());
drop policy if exists referral_rates_auth_read on public.referral_rate_config;create policy referral_rates_auth_read on public.referral_rate_config for select to authenticated using(enabled=true);
drop policy if exists referral_rewards_referrer_read on public.referral_rewards;create policy referral_rewards_referrer_read on public.referral_rewards for select using(referrer_id=auth.uid());
create or replace function public.ensure_referral_profile() returns text language plpgsql security definer set search_path=public as $$declare uid uuid:=auth.uid();existing text;candidate text;begin if uid is null then raise exception 'Authentication required';end if;select code into existing from public.referral_profiles where user_id=uid;if existing is not null then return existing;end if;candidate:=upper(substr(md5(uid::text||':'||clock_timestamp()::text),1,10));insert into public.referral_profiles(user_id,code)values(uid,candidate)on conflict(user_id)do update set user_id=excluded.user_id returning code into existing;return existing;end$$;
create or replace function public.claim_referral(p_code text) returns jsonb language plpgsql security definer set search_path=public,auth as $$declare uid uuid:=auth.uid();referrer uuid;created timestamptz;attr public.referral_attributions;begin if uid is null then raise exception 'Authentication required';end if;select user_id into referrer from public.referral_profiles where upper(code)=upper(trim(p_code));if referrer is null then raise exception 'Invalid referral code';end if;if referrer=uid then raise exception 'Self referral is not allowed';end if;select created_at into created from auth.users where id=uid;if created is null then raise exception 'User account not found';end if;if now()>created+interval '48 hours' then raise exception 'Referral window expired';end if;select * into attr from public.referral_attributions where referred_id=uid;if attr.id is not null then return jsonb_build_object('ok',true,'alreadyClaimed',true,'expiresAt',attr.expires_at);end if;insert into public.referral_attributions(referred_id,referrer_id,referral_code,attributed_at,expires_at)values(uid,referrer,upper(trim(p_code)),now(),created+interval '48 hours')returning * into attr;return jsonb_build_object('ok',true,'alreadyClaimed',false,'expiresAt',attr.expires_at);end$$;
revoke all on function public.ensure_referral_profile() from public;revoke all on function public.claim_referral(text) from public;grant execute on function public.ensure_referral_profile() to authenticated;grant execute on function public.claim_referral(text) to authenticated;
create or replace function public.award_first_referral_subscription() returns trigger language plpgsql security definer set search_path=public as $$declare attr public.referral_attributions;ref_plan text;rate numeric(6,5);amount numeric(14,2);prior_count integer;begin if new.status<>'active' or new.plan_id='free' then return new;end if;select * into attr from public.referral_attributions where referred_id=new.owner_id limit 1;if attr.id is null then return new;end if;select count(*) into prior_count from public.subscriptions where owner_id=new.owner_id and plan_id<>'free' and status='active' and id<>new.id and created_at<new.created_at;if prior_count>0 then return new;end if;if exists(select 1 from public.referral_rewards where attribution_id=attr.id)then return new;end if;select plan_id into ref_plan from public.subscriptions where owner_id=attr.referrer_id and status='active' and(expires_at is null or expires_at>now())order by created_at desc limit 1;ref_plan:=coalesce(ref_plan,'free');select commission_rate into rate from public.referral_rate_config where plan_id=ref_plan and enabled=true;rate:=coalesce(rate,0.15);if new.payment_request_id is not null then select amount_inr into amount from public.payment_requests where id=new.payment_request_id;end if;if amount is null then amount:=case new.plan_id when 'starter' then 1200 when 'pro' then 3499 when 'elite' then 5499 when 'ultra' then 7499 when 'prime' then 12499 else 0 end;end if;if coalesce(amount,0)<=0 then return new;end if;insert into public.referral_rewards(attribution_id,subscription_id,referrer_id,referred_id,referrer_plan_id,referred_plan_id,qualifying_amount,commission_rate,commission_amount,status)values(attr.id,new.id,attr.referrer_id,new.owner_id,ref_plan,new.plan_id,amount,rate,round(amount*rate,2),'pending')on conflict(attribution_id)do nothing;return new;end$$;
drop trigger if exists subscriptions_award_referral on public.subscriptions;create trigger subscriptions_award_referral after insert or update of status,plan_id,payment_request_id on public.subscriptions for each row execute function public.award_first_referral_subscription();
commit;
